def filter_requests(urls, allowed_hosts):
    kept = []
    for url in urls:
        if "://" not in url:
            continue
        rest = url.split("://", 1)[1]
        host = rest.split("/", 1)[0].split(":", 1)[0].lower()
        if host in {h.lower() for h in allowed_hosts}:
            kept.append(url)
    return kept

