import re

def find_dynamic_values(params):
    pattern = re.compile(r"^[A-Za-z0-9_\-]{20,}$")
    return sorted(name for name, value in params.items()
                  if pattern.match(value) and any(ch.isdigit() for ch in value) and any(ch.isalpha() for ch in value))
